/** The metal each glyph wears, keyed by app skin. `brand` is the original artwork. */
export const CAR_ICON_BY_SKIN = {
  crew:    { brand: CAR_ICON_CREW,    premium: CAR_ICON_CREW_PREMIUM,    ultra: CAR_ICON_CREW_ULTRA },
  compass: { brand: CAR_ICON_COMPASS, premium: CAR_ICON_COMPASS_PREMIUM, ultra: CAR_ICON_COMPASS_ULTRA },
  view3d:  { brand: CAR_ICON_VIEW_3D, premium: CAR_ICON_VIEW_3D_PREMIUM,  ultra: CAR_ICON_VIEW_3D_ULTRA },
  view2d:  { brand: CAR_ICON_VIEW_2D, premium: CAR_ICON_VIEW_2D_PREMIUM,  ultra: CAR_ICON_VIEW_2D_ULTRA },
} as const;

export type CarGlyph = keyof typeof CAR_ICON_BY_SKIN;

/** Resolve a glyph for the active skin. Unknown skins fall back to the brand art. */
export function carIcon(glyph: CarGlyph, skin: "brand" | "premium" | "ultra"): CarIcon {
  const set = CAR_ICON_BY_SKIN[glyph];
  return (set && (set as any)[skin]) || set.brand;
}
